er.", "section": "OPOZORILO! > 11.1 Rezultati pomivanja in sušenja niso zadovoljivi", "page_from": 55, "page_to": 55, "pdf_url": "/files/10.pdf#page=55", "images": [], "score": 0.15933539, "dense_rank": 15, "bm25_rank": null}]}

